-- M44 identity catalog: exact structure, owner and runner privileges. Read only.
DO $identity_verify$
DECLARE item record;actual jsonb;privilege_name text;
BEGIN
 IF NOT EXISTS(SELECT FROM forge_agent.schema_migrations WHERE version=44) THEN RETURN;END IF;
 IF NOT EXISTS(SELECT FROM forge_agent.schema_migrations WHERE version=44 AND name='identity_catalog') THEN RAISE EXCEPTION 'Identity catalog migration identity drift';END IF;
 FOR item IN SELECT * FROM(VALUES
('coding_identity_catalog',$catalog${"columns": [["identity_id", "uuid", true, "gen_random_uuid()"], ["owner_id", "text", true, null], ["project_alias", "text", true, null], ["kind", "text", true, null], ["subject", "text", true, null], ["generation", "integer", true, null], ["legacy_digest", "text", false, null], ["document", "jsonb", true, null], ["created_at", "timestamp with time zone", true, "clock_timestamp()"]], "constraints": [["coding_identity_catalog_document_check", "c", "CHECK ((jsonb_typeof(document) = 'object'::text))", true, false, false], ["coding_identity_catalog_generation_check", "c", "CHECK ((generation > 0))", true, false, false], ["coding_identity_catalog_kind_check", "c", "CHECK ((kind = ANY (ARRAY['workflow_policy'::text, 'external_workflow_policy'::text, 'recipe'::text])))", true, false, false], ["coding_identity_catalog_legacy_digest_check", "c", "CHECK (((legacy_digest IS NULL) OR (legacy_digest ~ '^[0-9a-f]{64}$'::text)))", true, false, false], ["coding_identity_catalog_owner_id_check", "c", "CHECK (((owner_id <> ''::text) AND (octet_length(owner_id) <= 128)))", true, false, false], ["coding_identity_catalog_owner_id_project_alias_kind_subject_key", "u", "UNIQUE (owner_id, project_alias, kind, subject, generation)", true, false, false], ["coding_identity_catalog_pkey", "p", "PRIMARY KEY (identity_id)", true, false, false], ["coding_identity_catalog_project_alias_check", "c", "CHECK ((project_alias ~ '^[A-Za-z0-9_.-]{1,64}$'::text))", true, false, false], ["coding_identity_catalog_subject_check", "c", "CHECK ((subject ~ '^[A-Za-z0-9_.:-]{1,160}$'::text))", true, false, false]], "force_row_security": false, "indexes": [["coding_identity_catalog_legacy_digest", "CREATE INDEX coding_identity_catalog_legacy_digest ON forge_agent.coding_identity_catalog USING btree (owner_id, project_alias, kind, legacy_digest)", true, true], ["coding_identity_catalog_owner_id_project_alias_kind_subject_key", "CREATE UNIQUE INDEX coding_identity_catalog_owner_id_project_alias_kind_subject_key ON forge_agent.coding_identity_catalog USING btree (owner_id, project_alias, kind, subject, generation)", true, true], ["coding_identity_catalog_pkey", "CREATE UNIQUE INDEX coding_identity_catalog_pkey ON forge_agent.coding_identity_catalog USING btree (identity_id)", true, true]], "kind": "r", "owner": "forge_agent_owner", "persistence": "p", "row_security": false, "triggers": []}$catalog$::jsonb,ARRAY['SELECT']::text[]),
('coding_task_identities',$catalog${"columns": [["owner_id", "text", true, null], ["project_alias", "text", true, null], ["task_id", "uuid", true, null], ["recipe_id", "uuid", true, null], ["workflow_id", "uuid", false, null], ["workflow_policy_id", "uuid", false, null], ["created_at", "timestamp with time zone", true, "clock_timestamp()"]], "constraints": [["coding_task_identities_check", "c", "CHECK (((workflow_id IS NULL) = (workflow_policy_id IS NULL)))", true, false, false], ["coding_task_identities_owner_id_project_alias_task_id_fkey", "f", "FOREIGN KEY (owner_id, project_alias, task_id) REFERENCES forge_agent.coding_tasks(owner_id, project_alias, id)", true, false, false], ["coding_task_identities_pkey", "p", "PRIMARY KEY (owner_id, project_alias, task_id)", true, false, false], ["coding_task_identities_recipe_id_fkey", "f", "FOREIGN KEY (recipe_id) REFERENCES forge_agent.coding_identity_catalog(identity_id)", true, false, false], ["coding_task_identities_workflow_id_fkey", "f", "FOREIGN KEY (workflow_id) REFERENCES forge_agent.coding_workflows(workflow_id)", true, false, false], ["coding_task_identities_workflow_policy_id_fkey", "f", "FOREIGN KEY (workflow_policy_id) REFERENCES forge_agent.coding_identity_catalog(identity_id)", true, false, false]], "force_row_security": false, "indexes": [["coding_task_identities_pkey", "CREATE UNIQUE INDEX coding_task_identities_pkey ON forge_agent.coding_task_identities USING btree (owner_id, project_alias, task_id)", true, true]], "kind": "r", "owner": "forge_agent_owner", "persistence": "p", "row_security": false, "triggers": []}$catalog$::jsonb,ARRAY['SELECT','INSERT']::text[])
 ) AS expected(name,data,runner) LOOP
  SELECT jsonb_build_object('kind',c.relkind,'persistence',c.relpersistence,'row_security',c.relrowsecurity,'force_row_security',c.relforcerowsecurity,'owner',pg_get_userbyid(c.relowner),
   'columns',(SELECT jsonb_agg(jsonb_build_array(a.attname,format_type(a.atttypid,a.atttypmod),a.attnotnull,pg_get_expr(d.adbin,d.adrelid)) ORDER BY a.attnum) FROM pg_attribute a LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped),
   'constraints',(SELECT coalesce(jsonb_agg(jsonb_build_array(x.conname,x.contype,pg_get_constraintdef(x.oid),x.convalidated,x.condeferrable,x.condeferred) ORDER BY x.conname),'[]') FROM pg_constraint x WHERE x.conrelid=c.oid),
   'indexes',(SELECT coalesce(jsonb_agg(jsonb_build_array(i.relname,pg_get_indexdef(i.oid),x.indisvalid,x.indisready) ORDER BY i.relname),'[]') FROM pg_index x JOIN pg_class i ON i.oid=x.indexrelid WHERE x.indrelid=c.oid),
   'triggers',(SELECT coalesce(jsonb_agg(jsonb_build_array(t.tgname,pg_get_triggerdef(t.oid),t.tgenabled) ORDER BY t.tgname),'[]') FROM pg_trigger t WHERE t.tgrelid=c.oid AND NOT t.tgisinternal))
  INTO actual FROM pg_class c WHERE c.relnamespace='forge_agent'::regnamespace AND c.relname=item.name;
  IF actual IS DISTINCT FROM item.data THEN RAISE EXCEPTION 'Identity catalog drift: %',item.name;END IF;
  FOREACH privilege_name IN ARRAY ARRAY['SELECT','INSERT','UPDATE','DELETE','TRUNCATE','REFERENCES','TRIGGER'] LOOP
   IF has_table_privilege('forge_agent','forge_agent.'||item.name,privilege_name) IS DISTINCT FROM (privilege_name=ANY(item.runner)) THEN RAISE EXCEPTION 'Identity catalog runner privilege drift: %',item.name;END IF;
  END LOOP;
  -- Only the owner, the runner and an optional read-only Muse reader may appear.
  IF EXISTS(SELECT FROM pg_class c,LATERAL aclexplode(c.relacl) a WHERE c.relnamespace='forge_agent'::regnamespace AND c.relname=item.name
   AND (a.grantee=0 OR a.is_grantable OR a.grantor<>'forge_agent_owner'::regrole
    OR (a.grantee NOT IN('forge_agent_owner'::regrole,'forge_agent'::regrole) AND NOT(pg_get_userbyid(a.grantee)='muse_events' AND a.privilege_type='SELECT')))) THEN
   RAISE EXCEPTION 'Identity catalog ACL drift: %',item.name;END IF;
 END LOOP;
 SELECT to_jsonb(jsonb_build_array(pg_get_userbyid(p.proowner),p.prosecdef,p.proconfig,ARRAY(SELECT unnest(p.proacl::text[]) ORDER BY 1))) INTO actual FROM pg_proc p WHERE p.oid=to_regprocedure('forge_agent.coding_identity_register(text,text,text,text,jsonb,text)');
 IF actual IS DISTINCT FROM '["forge_agent_owner", true, ["search_path=pg_catalog, pg_temp"], ["forge_agent=X/forge_agent_owner", "forge_agent_owner=X/forge_agent_owner"]]'::jsonb THEN RAISE EXCEPTION 'Identity catalog function drift';END IF;
END;
$identity_verify$;
